            capturedData.add(data);
            capturedStyles.add(style);
            Queue<String> q = new LinkedList<>();
            q.add("Q:" + data);
            return q;
        }
    }

    @Test
    public void testMakeColumnQueues_basic() {
        TestableTextHelpAppendable helper = new TestableTextHelpAppendable(new StringBuilder());

        List<String> columnData = Arrays.asList("one", "two", "three");
