        assertEquals(2, result.size());
        assertEquals(2, helper.capturedData.size());

        assertEquals("one", helper.capturedData.get(0));
        assertEquals("two", helper.capturedData.get(1));

        assertEquals(styles.get(0), helper.capturedStyles.get(0));
        assertEquals(styles.get(1), helper.capturedStyles.get(1));

        assertEquals("Q:one", result.get(0).peek());
        assertEquals("Q:two", result.get(1).peek());
    }

